select id, product_id, quantity, unit_price, lead(unit_price) over w_running next_unit_price, lead(quantity) over w_running next_quantity, lag(quantity) over w_running prev_quantity, row_number() over w_running row_seq, last_value(quantity) ignore nulls over (partition by product_id order by quantity, id rows between unbounded preceding and current row) last_known_quantity from order_items where product_id in (12, 27, 34) window w_running as (partition by order_id, product_id order by unit_price, id)
